// List of Munger document sources to ingest.
// Each entry defines a source with its URL (or placeholder for local files)
// and metadata tags for filtering during RAG retrieval.
//
// To ingest local files: use the 'Read Binary Files' node before this,
// or manually upload PDFs to n8n's file system and reference them here.

const sources = [
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/psychology_of_human_misjudgment.txt',
    title: 'The Psychology of Human Misjudgment',
    source: 'speech',
    year: 1995,
    category: 'mental_models'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/usc_law_commencement_1994.txt',
    title: 'Practical Thought About Practical Thought (USC Law 1994)',
    source: 'speech',
    year: 1994,
    category: 'wisdom_life'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/harvard_law_speech.txt',
    title: 'The Need for More Multidisciplinary Approach (Harvard Law 1998)',
    source: 'speech',
    year: 1998,
    category: 'mental_models'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/worldly_wisdom_speech.txt',
    title: 'A Lesson on Elementary Worldly Wisdom (USC Business 1994)',
    source: 'speech',
    year: 1994,
    category: 'investing_philosophy'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/djco_letters_compilation.txt',
    title: 'Daily Journal Corporation Annual Meeting Transcripts (2014-2023)',
    source: 'annual_meeting',
    year: '2014-2023',
    category: 'investing_current'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/wesco_letters_compilation.txt',
    title: 'Wesco Financial Annual Reports - Munger Letters (1977-2010)',
    source: 'annual_report',
    year: '1977-2010',
    category: 'investing_philosophy'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/berkshire_munger_sections.txt',
    title: 'Berkshire Hathaway Annual Meeting - Munger Remarks',
    source: 'annual_meeting',
    year: '1994-2023',
    category: 'investing_current'
  },
  {
    type: 'url',
    url: 'https://raw.githubusercontent.com/your-repo/munger-docs/main/poor_charlies_almanack_excerpts.txt',
    title: "Poor Charlie's Almanack - Selected Munger Talks",
    source: 'book',
    year: 2005,
    category: 'mental_models'
  },
  {
    type: 'text',
    text: 'ADD DIRECT TEXT CONTENT HERE - e.g. paste in transcript content directly',
    title: 'Manual Text Entry',
    source: 'manual',
    year: 2023,
    category: 'misc'
  }
];

// Filter to only fetch URL sources (skip manual text entries unless you want them)
return sources
  .filter(s => s.type === 'url' || s.type === 'text')
  .map(s => ({ json: s }));

// Merge fetched URL content with metadata from the source definition
const sourceData = $('Is URL Source?').item.json;
const fetchedContent = $input.first().json;

return [{
  json: {
    text: fetchedContent.data || fetchedContent.body || fetchedContent,
    metadata: {
      title: sourceData.title,
      source: sourceData.source,
      year: sourceData.year,
      category: sourceData.category,
      ingested_at: new Date().toISOString()
    }
  }
}];

// For direct text entries, just pass through with metadata
const source = $input.first().json;
return [{
  json: {
    text: source.text,
    metadata: {
      title: source.title,
      source: source.source,
      year: source.year,
      category: source.category,
      ingested_at: new Date().toISOString()
    }
  }
}];

// Log completion status for each document
const batchInfo = $('Process One at a Time').item.json;
console.log(`Ingested: ${batchInfo.title}`);
return [{ json: { status: 'ingested', title: batchInfo.title, timestamp: new Date().toISOString() } }];
